        self.is_end = False


class Solution:
    def replaceWords(self, dictionary: list[str], sentence: str) -> str:
        root = TrieNode()
        for word in dictionary:
            node = root
            for ch in word:
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
            node.is_end = True

        def shortest_root(word: str) -> str:
            node = root
            prefix = []
            for ch in word:
                if ch not in node.children:
                    return word  # no root prefixes this word
                prefix.append(ch)
                node = node.children[ch]
                if node.is_end:
                    return ''.join(prefix)  # first word-end = shortest root
            return word  # never hit a root end

        return ' '.join(shortest_root(w) for w in sentence.split(' '))

